import type { KnorviaAutomation, KnorviaAutomationCreateParams, KnorviaAutomationLifecycleStatus, ModelSelection, KnorviaAutomationRun, KnorviaAutomationRunDispatchStatus, KnorviaAutomationRunOutcome, KnorviaAutomationTrigger, KnorviaAutomationUpdateParams } from "@knorvia/shared";
export declare const DISPATCH_RETRY_BASE_MS = 30000;
export declare const DISPATCH_RETRY_CAP_MS = 900000;
export declare const DISPATCH_MAX_ATTEMPTS = 5;
export declare const CLAIM_STALE_MS = 600000;
export declare class AutomationCreateLimitError extends Error { readonly code: string; constructor(); }
export declare function computeRetryAt(now:number, attempts:number):number;
export declare class AutomationRepo {
  constructor(dbPath?:string,startupBusyTimeoutMs?:number);
  ensureReady(): Promise<void>;
  close(options?: { throwOnError?: boolean }): void;
  create(
    params: KnorviaAutomationCreateParams,
    options: { nextRunAt: number | null; lifecycleStatus?: KnorviaAutomationLifecycleStatus },
  ): Promise<KnorviaAutomation>;
  list(scope?: {
    workspacePath?: string;
    workspaceIdentity?: string;
  }): Promise<KnorviaAutomation[]>;
  getModelSelectionForDispatch(
    automationId: string,
    workspaceKey: string,
  ): Promise<ModelSelection | undefined>;
  hasTaskBinding(scope: {
    workspacePath: string;
    workspaceIdentity?: string;
    targetTaskId: string;
  }): Promise<boolean>;
  get(automationId: string, workspaceKey?: string): Promise<KnorviaAutomation | null>;
  getScheduledRunCount(automationId: string, workspaceKey?: string): Promise<number | null>;
  update(
    automationId: string,
    params: KnorviaAutomationUpdateParams,
    options?: {
      nextRunAt?: number | null;
      lifecycleStatus?: KnorviaAutomationLifecycleStatus;
      resetRetry?: boolean;
    },
    workspaceKey?: string,
  ): Promise<KnorviaAutomation | null>;
  delete(automationId: string, workspaceKey?: string): Promise<boolean>;
  setEnabled(automationId: string, enabled: boolean, workspaceKey?: string): Promise<void>;
  restart(
    automationId: string,
    options: { nextRunAt: number | null },
    workspaceKey?: string,
  ): Promise<void>;
  runNow(
    automationId: string,
    options: { now: number },
    workspaceKey?: string,
  ): Promise<{automation:KnorviaAutomation;run:KnorviaAutomationRun} | null>;
  claimDue(now: number): Promise<KnorviaAutomation[]>;
  claimManualRuns(now: number): Promise<{automation:KnorviaAutomation;run:KnorviaAutomationRun}[]>;
  markDispatched(
    automationId: string,
    options: { dispatchedAt: number; nextRunAt: number | null },
  ): Promise<void>;
  markDispatchFailed(
    automationId: string,
    options: {
      failedAt: number;
      error: string;
      kind: "transient" | "permanent";
      /** transient 达上限后，循环任务的下一个正常 next_run_at（调用方重算）。 */
      nextRunAt?: number | null;
    },
  ): Promise<void>;
  releaseClaim(automationId: string): Promise<void>;
  releaseManualClaim(automationId: string, workspaceKey: string): Promise<void>;
  touchManualClaim(automationId: string, workspaceKey: string): Promise<void>;
  skipAndReschedule(params: {
    automationId: string;
    runId: string;
    workspaceKey: string;
    scheduledAt: number | null;
    reason: string;
    nextRunAt: number | null;
    finalize?: boolean;
  }): Promise<void>;
  ensureRunClaimed(params: {
    runId: string;
    automationId: string;
    workspaceKey: string;
    scheduledAt: number | null;
    trigger: KnorviaAutomationTrigger;
  }): Promise<void>;
  upsertRunClaimed(params: {
    runId: string;
    automationId: string;
    workspaceKey: string;
    scheduledAt: number | null;
    trigger: KnorviaAutomationTrigger;
    modelSelection?: ModelSelection;
  }): Promise<void>;
  fixRunModelSelection(runId: string, selection: ModelSelection): Promise<ModelSelection>;
  markRunDispatch(params: {
    runId: string;
    dispatchStatus: KnorviaAutomationRunDispatchStatus;
    sessionId?: string | null;
    error?: string | null;
  }): Promise<void>;
  markManualRunDispatched(params: {
    runId: string;
    sessionId?: string | null;
    dispatchedAt: number;
  }): Promise<boolean>;
  markRunOutcome(
    runId: string,
    outcome: KnorviaAutomationRunOutcome,
    error?: string,
  ): Promise<void>;
  listUnsettledStudioWorkflowRuns(): Promise<
    Array<{
      automationRunId: string;
      automationId: string;
      workspaceKey: string;
      scheduledAt: number | null;
      trigger: KnorviaAutomationTrigger;
      studioRunId: string;
      workflowId: string;
    }>
  >;
  recordSkippedRun(params: {
    runId: string;
    automationId: string;
    workspaceKey: string;
    scheduledAt: number | null;
    trigger: KnorviaAutomationTrigger;
    reason: string;
  }): Promise<void>;
  listRuns(automationId: string, workspaceKey?: string): Promise<KnorviaAutomationRun[]>;
  getRun(runId: string): Promise<KnorviaAutomationRun | null>;
  deleteRun(runId: string, workspaceKey?: string): Promise<void>;
  pruneRuns(maxAgeMs: number): Promise<number>;
}

