    {
      "publicOperation": "hasTaskBinding",
      "text": "SELECT 1 AS bound FROM automations\n        WHERE workspace_key = @workspace_key AND target_task_id = @target_task_id\n        LIMIT 1"
    },
    {
      "publicOperation": "delete",
      "text": "DELETE FROM automations\n        WHERE automation_id = @id\n          AND (@workspace_key IS NULL OR workspace_key = @workspace_key)"
    },
    {
      "publicOperation": "setEnabled",
      "text": "UPDATE automations\n        SET enabled = @enabled,\n            lifecycle_status = @lifecycle_status,\n            updated_at = @now\n        WHERE automation_id = @id\n          AND (@workspace_key IS NULL OR workspace_key = @workspace_key)"
    },
    {
      "publicOperation": "restart",
      "text": "UPDATE automations\n        SET lifecycle_status = 'active',\n            enabled = 1,\n            run_count = 0,\n            scheduled_run_count = 0,\n            dispatch_attempts = 0,\n            retry_at = NULL,\n            dispatch_status = 'idle',\n            running = 0,\n            claimed_at = NULL,\n            next_run_at = @next_run_at,\n            last_error = NULL,\n            updated_at = @now\n        WHERE automation_id = @id\n          AND (@workspace_key IS NULL OR workspace_key = @workspace_key)"
