import { randomUUID } from "node:crypto";
import type { DatabaseSync } from "node:sqlite";
import type { KnorviaAutomation, KnorviaAutomationRun } from "@knorvia/shared";
import { readAutomation, transaction } from "./connection.js";
import { projectAutomation, projectRun } from "./rows.js";
import type { AutomationRow, RunRow } from "./rows.js";
import { sql } from "./sql.js";

export const CLAIM_STALE_MS = 600000;
export type ClaimedPair = { automation: KnorviaAutomation; run: KnorviaAutomationRun };
type JoinedRow = { [K in keyof AutomationRow as `a_${K}`]: AutomationRow[K] }
  & { [K in keyof RunRow as `r_${K}`]: RunRow[K] };

export function runNow(db: DatabaseSync, id: string, now: number, workspaceKey?: string): ClaimedPair | null {
  db.exec(sql.begin);
  try {
    db.prepare(sql.stale).run({ stale: now - CLAIM_STALE_MS });
    const automation = readAutomation(db, id, workspaceKey);
    if (!automation) { db.exec(sql.commit); return null; }
    const changed = db.prepare(sql.manualClaim).run({ id, now, workspace_key: workspaceKey ?? null });
    if (changed.changes !== 1) { db.exec(sql.commit); return null; }
    const runId = `${id}:manual:${randomUUID()}`;
    db.prepare(sql.manualInsert).run({
      run_id: runId, automation_id: id, workspace_key: automation.workspace_key,
      scheduled_at: now, model_selection: null, now,
    });
    db.exec(sql.commit);
    return {
      automation: projectAutomation({ ...automation, running: 1, claimed_at: now, updated_at: now }),
      run: projectRun({
        run_id: runId, automation_id: id, workspace_key: automation.workspace_key,
        scheduled_at: now, trigger: "manual", model_selection: null,
        dispatch_status: "claimed", attempts: 1, outcome: null, session_id: null, error: null,
        created_at: now, updated_at: now,
      }),
    };
  } catch (error) { db.exec(sql.rollback); throw error; }
}
export function claimDue(db: DatabaseSync, now: number): KnorviaAutomation[] {
  return transaction(db, () => {
    db.prepare(sql.expire).run({ now });
    db.prepare(sql.stale).run({ stale: now - CLAIM_STALE_MS });
    const rows = db.prepare(sql.due).all({ now }) as AutomationRow[];
    const claim = db.prepare(sql.dueClaim);
    const result: KnorviaAutomation[] = [];
    for (const row of rows) {
      if (claim.run({ id: row.automation_id, now }).changes === 1) {
        result.push(projectAutomation({ ...row, running: 1, claimed_at: now, dispatch_status: "claimed" }));
      }
    }
    return result;
  });
}
function joinedAutomation(row: JoinedRow, now: number): AutomationRow {
  return {
    automation_id: row.a_automation_id, title: row.a_title, cron_expr: row.a_cron_expr,
    prompt: row.a_prompt, model: row.a_model ?? null, provider: row.a_provider ?? null,
    model_selection: row.a_model_selection ?? null, mode: row.a_mode ?? null,
    thought_level: row.a_thought_level ?? null, workspace_key: row.a_workspace_key,
    workspace_path: row.a_workspace_path, workspace_identity: row.a_workspace_identity ?? null,
    target_task_id: row.a_target_task_id ?? null, studio_workflow_id: row.a_studio_workflow_id ?? null,
    location_kind: row.a_location_kind, recurring: row.a_recurring, max_runs: row.a_max_runs ?? null,
    end_at: row.a_end_at ?? null, schedule_rule: row.a_schedule_rule ?? null,
    schedule_edited_by_user: row.a_schedule_edited_by_user, run_count: row.a_run_count,
    scheduled_run_count: row.a_scheduled_run_count, enabled: row.a_enabled,
    lifecycle_status: row.a_lifecycle_status, next_run_at: row.a_next_run_at ?? null,
    last_run_at: row.a_last_run_at ?? null, running: 1, claimed_at: now,
    dispatch_status: row.a_dispatch_status, dispatch_attempts: row.a_dispatch_attempts,
    retry_at: row.a_retry_at ?? null, last_error: row.a_last_error ?? null,
    created_at: row.a_created_at, updated_at: now,
  };
}
function joinedRun(row: JoinedRow, now: number): RunRow {
  return {
    run_id: row.r_run_id, automation_id: row.r_automation_id, workspace_key: row.r_workspace_key,
    scheduled_at: row.r_scheduled_at ?? null, trigger: row.r_trigger,
    model_selection: row.r_model_selection ?? null, dispatch_status: row.r_dispatch_status,
    outcome: row.r_outcome ?? null, session_id: row.r_session_id ?? null, error: row.r_error ?? null,
    attempts: row.r_attempts + 1, created_at: row.r_created_at, updated_at: now,
  };
}
export function claimManualRuns(db: DatabaseSync, now: number): ClaimedPair[] {
  return transaction(db, () => {
    const stale = now - CLAIM_STALE_MS;
    db.prepare(sql.stale).run({ stale });
    const rows = db.prepare(sql.manualDue).all({ stale }) as JoinedRow[];
    const claim = db.prepare(sql.reclaimedManual);
    const attempt = db.prepare(sql.manualAttempt);
    const result: ClaimedPair[] = [];
    for (const row of rows) {
      if (claim.run({ id: row.a_automation_id, now }).changes !== 1) continue;
      attempt.run({ run_id: row.r_run_id, now });
      result.push({ automation: projectAutomation(joinedAutomation(row, now)), run: projectRun(joinedRun(row, now)) });
    }
    return result;
  });
}

import { mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { createRequire } from "node:module";
import type { DatabaseSync } from "node:sqlite";
import { getTasksIndexDatabasePath } from "#src/paths.js";
import { isTasksStorageMigrated } from "#src/session/tasksDatabase/prepared.js";
import { runTasksDatabaseMigrations } from "#src/session/tasksDatabase/migrations.js";
import { sql } from "./sql.js";
import type { AutomationRow } from "./rows.js";

export class Connection {
  private db: DatabaseSync | null = null;
  private boundPath: string | null = null;
  private ready: Promise<void> | null = null;
  private readonly override: string | null;
  constructor(dbPath?: string, private readonly startupBusyTimeoutMs = 5000) {
    this.override = dbPath?.trim() || null;
  }
  async ensureReady(): Promise<void> {
    const path = this.override ?? getTasksIndexDatabasePath();
    if (this.boundPath && this.boundPath !== path) this.close();
    if (!this.ready) {
      this.ready = this.initialize(path).catch((error: unknown) => {
        this.close();
        throw error;
      });
    }
    await this.ready;
  }
  private async initialize(path: string): Promise<void> {
    await mkdir(dirname(path), { recursive: true });
    if (!this.db) {
      const { DatabaseSync: NativeDatabase } = createRequire(import.meta.url)("node:sqlite") as {
        DatabaseSync: new (filename: string) => DatabaseSync;
      };
      this.db = new NativeDatabase(path);
      this.boundPath = path;
      this.db.exec(`PRAGMA busy_timeout = ${this.startupBusyTimeoutMs}`);
    }
    if (!isTasksStorageMigrated(path, this.db)) runTasksDatabaseMigrations(this.db);
    this.db.exec(sql.wal);
    this.db.exec(sql.normal);
  }
  close(options?: { throwOnError?: boolean }): void {
    let closeError: unknown;
    try { this.db?.close(); } catch (error) { closeError = error; }
    finally { this.db = null; this.boundPath = null; this.ready = null; }
    if (options?.throwOnError && closeError) throw closeError;
  }
  database(): DatabaseSync {
    if (!this.db) throw new Error("AutomationRepo 未初始化：请先 await ensureReady()");
    return this.db;
  }
}
export function readAutomation(db: DatabaseSync, id: string, workspaceKey?: string): AutomationRow | null {
  const row = db.prepare(sql.read).get({ id, workspace_key: workspaceKey ?? null });
  return row === undefined ? null : row as AutomationRow;
}
export function transaction<T>(db: DatabaseSync, body: () => T): T {
  db.exec(sql.begin);
  try {
    const result = body();
    db.exec(sql.commit);
    return result;
  } catch (error) {
    db.exec(sql.rollback);
    throw error;
  }
}

import { randomUUID } from "node:crypto";
import type { DatabaseSync } from "node:sqlite";
import { AUTOMATION_CREATE_LIMIT, AUTOMATION_CREATE_LIMIT_ERROR_CODE, resolveWorkspaceKey } from "@knorvia/shared";
import type {
  KnorviaAutomation, KnorviaAutomationCreateParams, KnorviaAutomationLifecycleStatus,
  KnorviaAutomationUpdateParams, ModelSelection,
} from "@knorvia/shared";
import { readAutomation, transaction } from "./connection.js";
import { projectAutomation, readSelection, writeSelection } from "./rows.js";
import type { AutomationRow } from "./rows.js";
import { sql } from "./sql.js";

export class AutomationCreateLimitError extends Error {
  readonly code = AUTOMATION_CREATE_LIMIT_ERROR_CODE;
  constructor() {
    super(`[${AUTOMATION_CREATE_LIMIT_ERROR_CODE}] At most ${AUTOMATION_CREATE_LIMIT} automations may be retained. Delete an existing automation before creating another.`);
    this.name = "AutomationCreateLimitError";
  }
}
export type CreateOptions = { nextRunAt: number | null; lifecycleStatus?: KnorviaAutomationLifecycleStatus };
export type UpdateOptions = {
  nextRunAt?: number | null; lifecycleStatus?: KnorviaAutomationLifecycleStatus; resetRetry?: boolean;
};
export function create(db: DatabaseSync, params: KnorviaAutomationCreateParams, options: CreateOptions): KnorviaAutomation {
  const now = Date.now();
  const id = `automation-${randomUUID()}`;
  const workspaceKey = resolveWorkspaceKey({ workspacePath: params.workspacePath, workspaceIdentity: params.workspaceIdentity });
  transaction(db, () => {
    const row = db.prepare(sql.count).get() as { count: number | bigint };
    if (Number(row.count) >= AUTOMATION_CREATE_LIMIT) throw new AutomationCreateLimitError();
    db.prepare(sql.create).run({
      automation_id: id, title: params.title, cron_expr: params.cronExpr, prompt: params.prompt,
      model: null, provider: null, model_selection: writeSelection(params.modelSelection) ?? "null",
      workspace_key: workspaceKey, workspace_path: params.workspacePath,
      workspace_identity: params.workspaceIdentity ?? null, target_task_id: params.targetTaskId ?? null,
      studio_workflow_id: params.studioWorkflowId ?? null, recurring: params.recurring ? 1 : 0,
      max_runs: params.maxRuns ?? null, end_at: params.endAt ?? null,
      schedule_rule: params.scheduleRule ? JSON.stringify(params.scheduleRule) : null,
      enabled: options.lifecycleStatus === "completed" ? 0 : 1, lifecycle_status: options.lifecycleStatus ?? "active",
      next_run_at: options.nextRunAt, mode: params.mode ?? null, thought_level: null, created_at: now, updated_at: now,
    });
  });
  return projectAutomation(readAutomation(db, id)!);
}
export function list(db: DatabaseSync, scope?: { workspacePath?: string; workspaceIdentity?: string }): KnorviaAutomation[] {
  const workspaceKey = scope?.workspacePath ? resolveWorkspaceKey({ workspacePath: scope.workspacePath, workspaceIdentity: scope.workspaceIdentity }) : null;
  return (db.prepare(sql.list).all({ workspace_key: workspaceKey }) as AutomationRow[]).map(projectAutomation);
}
export function getModelSelectionForDispatch(db: DatabaseSync, automationId: string, workspaceKey: string): ModelSelection | undefined {
  const row = readAutomation(db, automationId, workspaceKey);
  if (!row) throw new Error("Automation 不存在或不属于当前工作区");
  const selection = readSelection(row.model_selection);
  if (selection) return selection;
  if (row.model_selection === "null") return undefined;
  throw new Error("Automation 模型选择不可用，请重新选择模型与思考档位");
}
export function hasTaskBinding(db: DatabaseSync, scope: { workspacePath: string; workspaceIdentity?: string; targetTaskId: string }): boolean {
  const workspaceKey = resolveWorkspaceKey({ workspacePath: scope.workspacePath, workspaceIdentity: scope.workspaceIdentity });
  return db.prepare(sql.binding).get({ workspace_key: workspaceKey, target_task_id: scope.targetTaskId }) !== undefined;
}
export function update(db: DatabaseSync, automationId: string, params: KnorviaAutomationUpdateParams, options?: UpdateOptions, workspaceKey?: string): KnorviaAutomation | null {
  const row = readAutomation(db, automationId, workspaceKey);
  if (!row) return null;
  const now = Date.now();
  const next: AutomationRow = {
    ...row, title: params.title ?? row.title, cron_expr: params.cronExpr ?? row.cron_expr,
    prompt: params.prompt ?? row.prompt,
    model_selection: params.modelSelection === undefined ? row.model_selection : writeSelection(params.modelSelection ?? undefined) ?? "null",
    mode: params.mode === undefined ? row.mode : params.mode,
    recurring: params.recurring === undefined ? row.recurring : params.recurring ? 1 : 0,
    max_runs: params.maxRuns === undefined ? row.max_runs : params.maxRuns,
    end_at: params.endAt === undefined ? row.end_at : params.endAt,
    schedule_rule: params.scheduleRule === undefined ? row.schedule_rule : params.scheduleRule ? JSON.stringify(params.scheduleRule) : null,
    schedule_edited_by_user: params.scheduleEditedByUser === undefined ? row.schedule_edited_by_user : params.scheduleEditedByUser ? 1 : 0,
    next_run_at: options?.nextRunAt === undefined ? row.next_run_at : options.nextRunAt,
    lifecycle_status: options?.lifecycleStatus ?? row.lifecycle_status,
    dispatch_attempts: options?.resetRetry ? 0 : row.dispatch_attempts,
    retry_at: options?.resetRetry ? null : row.retry_at,
    dispatch_status: options?.resetRetry ? "idle" : row.dispatch_status,
    enabled: options?.lifecycleStatus ? options.lifecycleStatus === "active" ? 1 : 0 : row.enabled,
    updated_at: now,
  };
  db.prepare(sql.update).run({
    automation_id: next.automation_id, title: next.title, cron_expr: next.cron_expr, prompt: next.prompt,
    model: next.model, provider: next.provider, model_selection: next.model_selection,
    mode: next.mode, thought_level: next.thought_level, recurring: next.recurring, max_runs: next.max_runs,
    end_at: next.end_at, schedule_rule: next.schedule_rule, schedule_edited_by_user: next.schedule_edited_by_user,
    next_run_at: next.next_run_at, lifecycle_status: next.lifecycle_status,
    dispatch_attempts: next.dispatch_attempts, retry_at: next.retry_at, dispatch_status: next.dispatch_status,
    enabled: next.enabled, updated_at: next.updated_at,
  });
  return projectAutomation(next);
}

import type { DatabaseSync } from "node:sqlite";
import { readAutomation } from "./connection.js";
import { sql } from "./sql.js";

export const DISPATCH_RETRY_BASE_MS = 30000;
export const DISPATCH_RETRY_CAP_MS = 900000;
export const DISPATCH_MAX_ATTEMPTS = 5;
export function computeRetryAt(now: number, attempts: number): number {
  return now + Math.min(DISPATCH_RETRY_BASE_MS * 2 ** Math.max(0, attempts - 1), DISPATCH_RETRY_CAP_MS);
}
export function markDispatched(db: DatabaseSync, id: string, options: { dispatchedAt: number; nextRunAt: number | null }): void {
  const row = readAutomation(db, id);
  if (!row) return;
  const scheduledCount = row.scheduled_run_count + 1;
  const maxReached = row.recurring === 0 && scheduledCount >= (row.max_runs ?? 1);
  const endReached = row.end_at !== null && (options.nextRunAt ?? Infinity) > row.end_at;
  const completed = maxReached || endReached;
  db.prepare(sql.dispatched).run({
    id, run_count: row.run_count + 1, scheduled_run_count: scheduledCount,
    dispatched_at: options.dispatchedAt, lifecycle_status: completed ? "completed" : "active",
    enabled: completed ? 0 : 1, next_run_at: completed ? null : options.nextRunAt, now: options.dispatchedAt,
  });
}
export function markDispatchFailed(db: DatabaseSync, id: string, options: {
  failedAt: number; error: string; kind: "transient" | "permanent"; nextRunAt?: number | null;
}): void {
  const row = readAutomation(db, id);
  if (!row) return;
  const fields = { id, error: options.error, now: options.failedAt };
  if (options.kind === "permanent") { db.prepare(sql.permanentFailure).run(fields); return; }
  const attempts = row.dispatch_attempts + 1;
  if (attempts >= DISPATCH_MAX_ATTEMPTS) {
    if (row.recurring === 1) {
      db.prepare(sql.recurringFailure).run({ ...fields, next_run_at: options.nextRunAt ?? null });
    } else db.prepare(sql.exhaustedFailure).run(fields);
    return;
  }
  db.prepare(sql.retry).run({ ...fields, attempts, retry_at: computeRetryAt(options.failedAt, attempts) });
}

import { knorviaTaskModeSchema, modelSelectionSchema } from "@knorvia/shared";
