  schedule_rule: string | null; schedule_edited_by_user: number;
  run_count: number; scheduled_run_count: number; enabled: number;
  lifecycle_status: KnorviaAutomation["lifecycleStatus"];
  next_run_at: number | null; last_run_at: number | null; running: number; claimed_at: number | null;
  dispatch_status: KnorviaAutomation["dispatchStatus"]; dispatch_attempts: number;
  retry_at: number | null; last_error: string | null; created_at: number; updated_at: number;
