import { transaction } from "./connection.js";
import { readSelection, writeSelection } from "./rows.js";
import { sql } from "./sql.js";

export type RunIdentity = {
  runId: string; automationId: string; workspaceKey: string; scheduledAt: number | null;
};
export type RunClaim = RunIdentity & { trigger: KnorviaAutomationTrigger };
export function runBindings(params: RunIdentity, now: number) {
  return {
    run_id: params.runId, automation_id: params.automationId, workspace_key: params.workspaceKey,
    scheduled_at: params.scheduledAt, now,
  };
}
export function skipAndReschedule(db: DatabaseSync, params: RunIdentity & {
  reason: string; nextRunAt: number | null; finalize?: boolean;
}): void {
  const now = Date.now();
  transaction(db, () => {
    db.prepare(sql.scheduleSkip).run({ ...runBindings(params, now), reason: params.reason });
    if (params.finalize) db.prepare(sql.finalize).run({ id: params.automationId, now });
    else db.prepare(sql.reschedule).run({ id: params.automationId, next_run_at: params.nextRunAt, now });
  });
}
export function ensureRunClaimed(db: DatabaseSync, params: RunClaim): void {
  const now = Date.now();
  db.prepare(sql.ensureRun).run({ ...runBindings(params, now), trigger: params.trigger });
}
export function upsertRunClaimed(db: DatabaseSync, params: RunClaim & { modelSelection?: ModelSelection }): void {
  const now = Date.now();
